import{z as n,x as i,o as e,c as d,q as t,j as A,D as E,d as o,s,S as B,b as l}from"./chunks/framework.C8m1ZpeB.js";const u=JSON.parse('{"title":"Dolev–Yao","description":"","frontmatter":{"title":"Dolev–Yao","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/dolev-yao.md","filePath":"cs/dolev-yao.md","lastUpdated":1791413859000}'),D={name:"cs/dolev-yao.md"};function p(c,a,m,h,F,f){const r=i("Mermaid");return e(),d("div",null,[a[2]||(a[2]=t('<h1 id="dolev–yao" tabindex="-1">Dolev–Yao <a class="header-anchor" href="#dolev–yao" aria-label="Permalink to &quot;Dolev–Yao&quot;">​</a></h1><div class="epigraph"><p>网络敌手可以拆、拼、重放它看见的项，但不能从密文算出明文，除非它有密钥——协议在这个代数里证明安全或不安全。</p><footer>—— Dolev and Yao, On the Security of Public Key Protocols, IEEE TIT 1983；Anderson 对协议假设的整理</footer></div><p><a href="/cs/stride">上一课</a>用清单问数据流图。本课不重列六类。缺口是协议课的敌手：不是「黑客」口号，而是形式化能力。Dolev–Yao：控制信道，任意组合已知消息，密码原语当黑盒。后课对称加密在此模型里才有「够用的那一层」。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>STRIDE 的「篡改/伪造」在网上太宽。Needham–Schroeder 一类协议要问：在能改包的敌手下，认证还是否成立。Dolev–Yao 把加密当成理想锁：没有钥匙打不开，有钥匙可以构造新项。缺口是<strong>协议分析的默认敌手</strong>，不是某一分组算法。</p><p><span class="marginnote">计算模型（概率多项式时间）更细，后课只在需要时点名。侧信道不在 DY 里，后课瞬态执行再扩展模型。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>消息是项：原子、对、加密。敌手封闭于投影、配对、用已知键加解密、重放。协议是角色进程。安全目标写成「敌手项集里不出现某秘密」或「会话绑定到声称身份」。本课不跑具体攻击轨迹。</p>',8)),(e(),A(B,null,{default:E(()=>[s(r,{id:"mermaid-22",class:"mermaid",graph:"flowchart%20TD%0A%20%20CH%5B%22%E4%BF%A1%E9%81%93%E7%94%B1%E6%95%8C%E6%89%8B%E4%B8%AD%E7%BB%A7%22%5D%20--%3E%20DY%5B%22%E6%8B%86%E5%88%86%20%2F%20%E9%85%8D%E5%AF%B9%20%2F%20%E9%87%8D%E6%94%BE%22%5D%0A%20%20DY%20--%3E%20BOX%5B%22%E6%97%A0%E5%AF%86%E9%92%A5%E4%B8%8D%E8%83%BD%E5%BC%80%E5%AF%86%E6%96%87%22%5D%0A%20%20BOX%20--%3E%20GOAL%5B%22%E7%A7%98%E5%AF%86%E4%B8%8D%E5%87%BA%E7%8E%B0%E5%9C%A8%E6%95%8C%E6%89%8B%E9%A1%B9%E9%9B%86%22%5D%0A"})]),fallback:E(()=>[...a[0]||(a[0]=[o(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=l("h2",{id:"机制",tabindex:"-1"},[o("机制 "),l("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[4]||(a[4]=l("p",null,"把敌手钉成代数，后课 TLS、Kerberos 才能说「防的是 DY 主动者，不防已泄露的私钥」。Kerckhoffs 已在威胁模型课：算法公开。DY 再加：算法理想。真实分组模式若误用，会漏出 DY 假定锁不住的性质——下一单元对称加密与模式。",-1)),(e(),A(B,null,{default:E(()=>[s(r,{id:"mermaid-29",class:"mermaid",graph:"flowchart%20LR%0A%20%20ADV%5B%22DY%20%E6%95%8C%E6%89%8B%22%5D%20--%3E%20CAN1%5B%22%E6%8B%86%E6%B6%88%E6%81%AF%EF%BC%9A%E5%8F%96%E5%8A%A0%E5%AF%86%E9%A1%B9%E7%9A%84%E7%BB%84%E6%88%90%E9%83%A8%E5%88%86%22%5D%0A%20%20ADV%20--%3E%20CAN2%5B%22%E9%87%8D%E7%BB%84%EF%BC%9A%E7%94%A8%E5%B7%B2%E7%9F%A5%E5%AF%86%E9%92%A5%E5%8A%A0%E5%AF%86%E4%BB%BB%E6%84%8F%E9%A1%B9%22%5D%0A%20%20ADV%20--%3E%20CAN3%5B%22%E9%87%8D%E6%94%BE%EF%BC%9A%E6%8A%8A%E6%97%A7%E6%B6%88%E6%81%AF%E5%8E%9F%E6%A0%B7%E6%88%96%E6%94%B9%E5%A4%B4%E5%86%8D%E5%8F%91%22%5D%0A%20%20ADV%20--%3E%20CANT%5B%22%E4%B8%8D%E8%83%BD%EF%BC%9A%E6%97%A0%E5%AF%86%E9%92%A5%E4%BB%8E%E5%AF%86%E6%96%87%E8%BF%98%E5%8E%9F%E6%98%8E%E6%96%87%22%5D%0A%20%20CANT%20--%3E%20OUT%5B%22%E6%A8%A1%E5%9E%8B%E5%A4%96%EF%BC%9A%E4%BE%A7%E4%BF%A1%E9%81%93%E3%80%81%E5%BC%B1%E9%9A%8F%E6%9C%BA%E3%80%81%E7%A7%81%E9%92%A5%E6%B3%84%E9%9C%B2%22%5D%0A"})]),fallback:E(()=>[...a[1]||(a[1]=[o(" Loading... ",-1)])]),_:1})),a[5]||(a[5]=t('<p><span class="marginnote">术语翻译：Dolev–Yao 模型就是「把整条网络交给攻击者全权控制，同时把密码算法当成打不开的完美保险箱」的分析方法。它故意把两头都推到极端——网络最坏、密码最好——从而把安全问题只聚焦在协议逻辑本身。</span></p><p><span class="marginnote">直觉类比：DY 的项代数像乐高积木。攻击者可以捡到散落积木、拆开拼好的作品、按图纸重组，甚至加上自己已有的积木；但它不能凭空把一块积木变成它没有的新形状——那一步对应「没有密钥就解不开密文」。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不把模型检测工具当必会软件。共享密钥下明文如何藏进密文，下一课对称加密。</p><p><span class="marginnote">常见误区：初学者容易以为「协议在 DY 模型下证明了安全」就等于绝对安全。实际上模型里只覆盖理想化的密码原语——侧信道、弱随机数、私钥被偷、算法实现有洞都不在内。证明说的是「只要锁真的完美，逻辑就站得住」。</span></p><p>后课默认：协议敌手是 DY 主动者。对称密码服务「无密钥则不可读」。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>Dolev–Yao：控制网络，密码当理想锁。</li><li>不覆盖侧信道与弱随机数。</li><li>对称加密下一课。</li><li>出处：Dolev and Yao, <em>IEEE TIT</em> 1983；Anderson。</li></ul>',8))])}const C=n(D,[["render",p]]);export{u as __pageData,C as default};
